        + [M(f"How do you say “very {e}” by doubling the adjective?", d, dd([x[2] for x in _TRIP], d), d) for a, n, d, r, e in _TRIP]
        + [M(f"How do you say “very {e}” with ang + root?", r, dd([x[3] for x in _TRIP], r), r) for a, n, d, r, e in _TRIP]
